"use client"

import {
    Folder,
    Forward,
    MoreHorizontal,
    Trash2,
    MessageSquare,
} from "lucide-react"

import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuSeparator,
    DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import {
    SidebarGroup,
    SidebarGroupLabel,
    SidebarMenu,
    SidebarMenuAction,
    SidebarMenuButton,
    SidebarMenuItem,
    useSidebar,
} from "@/components/ui/sidebar"
import { useChatStore } from "@/stores/ChatStore"
import Link from "next/link"
import { useEffect, useState } from "react"

export function NavChatHistory() {
    const { isMobile } = useSidebar()
    // We'll hydrate the store or assume it's available. 
    // Using getRecentChats needs to be reactive.
    // Ideally, we just select all chats and slice them, or the store has a specific selector.
    // The logic 'getRecentChats' is a function, not a state selector, so we might need to wrap it or select 'chats' and sort manually.

    const chats = useChatStore((state) => state.chats);
    const [recentChats, setRecentChats] = useState(chats);

    useEffect(() => {
        // Sort and slice when chats change
        const sorted = [...chats]
            .sort((a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime())
            .slice(0, 5);
        setRecentChats(sorted);
    }, [chats]);

    const deleteChat = useChatStore((state) => state.deleteChat);

    return (
        <SidebarGroup className="group-data-[collapsible=icon]:hidden">
            <SidebarGroupLabel>Recent Chats</SidebarGroupLabel>
            <SidebarMenu>
                {recentChats.map((item) => (
                    <SidebarMenuItem key={item.id}>
                        <SidebarMenuButton asChild>
                            <Link href={`/c/${item.id}`}>
                                <MessageSquare className="text-muted-foreground" />
                                <span>{item.title}</span>
                            </Link>
                        </SidebarMenuButton>
                        <DropdownMenu>
                            <DropdownMenuTrigger asChild>
                                <SidebarMenuAction showOnHover>
                                    <MoreHorizontal />
                                    <span className="sr-only">More</span>
                                </SidebarMenuAction>
                            </DropdownMenuTrigger>
                            <DropdownMenuContent
                                className="w-48 rounded-lg"
                                side={isMobile ? "bottom" : "right"}
                                align={isMobile ? "end" : "start"}
                            >
                                <DropdownMenuItem onClick={() => { /* View Logic */ }}>
                                    <Folder className="text-muted-foreground" />
                                    <span>View Chat</span>
                                </DropdownMenuItem>
                                <DropdownMenuItem>
                                    <Forward className="text-muted-foreground" />
                                    <span>Share Chat</span>
                                </DropdownMenuItem>
                                <DropdownMenuSeparator />
                                <DropdownMenuItem onClick={() => deleteChat(item.id)}>
                                    <Trash2 className="text-muted-foreground" />
                                    <span>Delete Chat</span>
                                </DropdownMenuItem>
                            </DropdownMenuContent>
                        </DropdownMenu>
                    </SidebarMenuItem>
                ))}
                <SidebarMenuItem>
                    <SidebarMenuButton asChild className="text-sidebar-foreground/70">
                        <Link href="/history">
                            <MoreHorizontal className="text-sidebar-foreground/70" />
                            <span>View All History</span>
                        </Link>
                    </SidebarMenuButton>
                </SidebarMenuItem>
            </SidebarMenu>
        </SidebarGroup>
    )
}
